\documentclass{article}
% A0 portrait: paperwidth=841mm, paperheight=1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc}
\pagestyle{empty}

% ── Dark Sophisticated Color Theme ──
\definecolor{primary}{HTML}{0B1120}       % deep navy background
\definecolor{secondary}{HTML}{F59E0B}     % gold accent
\definecolor{accent}{HTML}{3B82F6}        % electric blue
\definecolor{bgposter}{HTML}{0B1120}      % poster background
\definecolor{cardbg}{HTML}{111827}        % card background
\definecolor{cardbggold}{HTML}{1A1508}    % gold-tinted card
\definecolor{cardbgblue}{HTML}{0A1525}    % blue-tinted card
\definecolor{textwhite}{HTML}{F8FAFC}     % primary text
\definecolor{textgray}{HTML}{94A3B8}      % muted text
\definecolor{gridcolor}{HTML}{1E293B}     % borders/dividers
\definecolor{stathighlight}{HTML}{1E293B} % stat box bg

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design, dark mode) ──
\tcbset{
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbggold,
    borderline west={6pt}{0pt}{secondary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.25},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbgblue,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.25},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{textwhite},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={textgray!50},
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary!12!primary,
    borderline west={8pt}{0pt}{secondary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=2mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{82}{98}\selectfont\bfseries\color{textwhite} The World's Most Valuable Companies}\\[14pt]
  {\fontsize{38}{46}\selectfont\color{textgray} A comparative snapshot of global market capitalization in 2025}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{textgray!70} 10,796 companies tracked \textbullet\ \$142.9 trillion total market value}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{secondary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{secondary} \$4.82T}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textgray} NVIDIA \#1}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{accent} 11}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textgray} Trillion-Dollar Club}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{secondary} 15/20}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textgray} U.S. Companies}\vspace{10pt}%
    }}
  \end{minipage}
}

% ══ ROW A: Column 1 — Overview + Sector ══
\posterbox[darkcard, title={Overview}
]{name=overview, column=1, between=row6 and row11}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item 10,796 public companies tracked globally
    \item Combined market cap: \textbf{\$142.9 trillion}
    \item Top 5 alone = \textbf{\$18.5T} (13\% of total)
    \item Tech and semiconductors dominate the top tier
  \end{itemize}
  \vspace{8pt}
  {\colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{30}{38}\selectfont\color{secondary}\bfseries NVIDIA > bottom 5,000+ companies combined}\vspace{6pt}%
  }}}
}

% ══ ROW A: Column 2 — Trillion-Dollar Club (hero chart) ══
\posterbox[goldcard, title={The Trillion-Dollar Club}
]{name=trillion, column=2, between=row6 and row14}{
  \posterfig{0.98}{figures/chart_trillion_club.png}{Eleven companies have crossed the trillion-dollar threshold. The top five alone exceed \$18.5T.}
}

% ══ ROW A: Column 3 — Country Dominance ══
\posterbox[bluecard, title={Country Dominance}
]{name=country, column=3, between=row6 and row11}{
  \posterfig{0.98}{figures/chart_countries.png}{15 of the top 20 companies are headquartered in the United States.}
  \vspace{6pt}
  {\fontsize{30}{38}\selectfont\color{textgray}
  The remaining five: Taiwan (TSMC), Saudi Arabia (Saudi Aramco), South Korea (Samsung), China (Tencent), Netherlands (ASML).}
}

% ══ ROW B: Column 1 — Sector Breakdown ══
\posterbox[bluecard, title={Sector Concentration}
]{name=sector, column=1, between=row11 and row16}{
  \posterfig{0.98}{figures/chart_sectors.png}{Technology and semiconductors dominate; only three non-tech entries in the top 11.}
  \vspace{8pt}
  {\fontsize{30}{38}\selectfont\color{textgray}
  Non-tech: Saudi Aramco (energy), Tesla (auto/energy), Berkshire Hathaway (diversified).}
}

% ══ ROW B: Column 2 — Scale in Context (continues from hero chart) ══
\posterbox[goldcard, title={Scale in Context}
]{name=scale, column=2, between=row14 and row20}{
  \posterfig{0.98}{figures/chart_context.png}{The top 10 hold \$25.4T --- 17.8\% of all tracked value across nearly 11,000 firms.}
}

% ══ ROW B: Column 3 — Key Insights (continues from country) ══
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row11 and row20}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item \textbf{Extreme concentration:} 0.09\% of firms hold 18\% of global value
    \item \textbf{9x drop} from rank 1 (\$4.82T) to rank 20 (\$554B)
    \item \textbf{AI-driven growth:} NVIDIA and Broadcom lead the surge
    \item \textbf{U.S. tech hegemony:} 15 of 20, across chips, software, and platforms
  \end{itemize}
  \vspace{14pt}
  {\colorbox{accent!18}{\parbox{0.92\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{32}{40}\selectfont\color{accent}\bfseries Top 10 = \$25.4T out of \$142.9T total}\vspace{4pt}\\
    {\fontsize{28}{36}\selectfont\color{textgray} A handful of firms reshape the global economic hierarchy}\vspace{8pt}%
  }}}
}

\end{tcbposter}
\end{document}
